app.use(session(app));

// Initialize database
db.serialize(() => {
  db.run(`CREATE TABLE IF NOT EXISTS merchants (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    email TEXT UNIQUE,
    name TEXT,
    password TEXT
  )`);

  db.run(`CREATE TABLE IF NOT EXISTS wares (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT,
    description TEXT,
    price REAL,
    merchant_id INTEGER,
    FOREIGN KEY (merchant_id) REFERENCES merchants(id)
  )`);
});

// Helper function to parse CSV
function parseCSV(csvString) {
  return new Promise((resolve, reject) => {
    const results = [];
    const stream = Readable.from([csvString]);
    stream
      .pipe(csvParser())
      .on('data', (data) => results.push(data))
      .on('end', () => resolve(results))
      .on('error', (err) => reject(err));
  });
}

// Authentication middleware
async function authenticate(ctx, next) {
  const token = ctx.cookies.get('AUTH_COOKIE');
  if (!token) {
    ctx.status = 401;
    ctx.body = { error: 'Unauthorized' };
    return;
  }

  try {
    const decoded = jwt.verify(token, APP_SECRET);
    ctx.state.merchantId = decoded.id;
    await next();
  } catch (err) {
    ctx.status = 401;
    ctx.body = { error: 'Unauthorized' };
  }
}

// Routes
router.post('/merchants/register', async (ctx) => {
  const { email, name, password } = ctx.request.body;
  if (!email || !name || !password) {
    ctx.status = 400;
    ctx.body = 'Invalid input';
    return;
  }

  const hashedPassword = await bcrypt.hash(password, 10);

  db.run(
    `INSERT INTO merchants (email, name, password) VALUES (?, ?, ?)`,
    [email, name, hashedPassword],
    function (err) {
      if (err) {
        ctx.status = 400;
        ctx.body = 'Invalid input';
      } else {
        ctx.status = 201;
        ctx.body = 'Merchant registered successfully';
      }
    }
  );
});

router.post('/merchants/login', async (ctx) => {
