  db.run(`INSERT INTO carts (cart_id) VALUES (?)`, [cartId], function(err) {
    if (err) {
      ctx.status = 500;
      ctx.body = { error: 'Failed to create cart' };
    } else {
      ctx.status = 201;
      ctx.body = { cart_id: cartId };
    }
  });
