      ctx.status = 404;
      ctx.body = { error: 'Cart not found' };
    } else {
      db.all(`SELECT item_id, count FROM cart_items WHERE cart_id = ?`, [cart_id], (err, items) => {
        if (err) {
          ctx.status = 500;
          ctx.body = { error: 'Database error' };
